#!/usr/bin/env python3

"""Check that HTML lexer/parser fixture Python scripts compile."""

from __future__ import annotations

import argparse
import py_compile
import tempfile
from pathlib import Path


FIXTURE_DIR = Path(__file__).resolve().parent
RUST_DIR = FIXTURE_DIR.parents[2]
PARSER_FIXTURE_DIR = RUST_DIR / "html-parser" / "tests" / "fixtures"
SCRIPT_INVENTORY = FIXTURE_DIR / "html-fixture-scripts.txt"
SCRIPT_GLOB = "*.py"


def main() -> int:
    args = parse_args()
    script_paths = fixture_scripts()
    script_inventory = [relative_script(script_path) for script_path in script_paths]

    if args.write_inventory:
        write_inventory(script_inventory)
        return 0

    errors: list[str] = []
    with tempfile.TemporaryDirectory(prefix="html-fixture-pycompile-") as temp_dir:
        temp_path = Path(temp_dir)
        for script_path in script_paths:
            target = temp_path / f"{script_path.stem}.pyc"
            try:
                py_compile.compile(
                    str(script_path),
                    cfile=str(target),
                    doraise=True,
                )
            except py_compile.PyCompileError as exc:
                errors.append(f"{relative_script(script_path)}: {exc.msg}")

    inventory_errors = check_inventory(script_inventory)

    print("HTML fixture Python scripts")
    print(f"scripts: {len(script_paths)}")

    errors.extend(inventory_errors)
    if errors:
        raise SystemExit("\n\n".join(errors))
    return 0


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description=(
            "Compile all checked-in Python fixture helpers and generators for "
            "the Rust HTML lexer/parser conformance corpora."
        )
    )
    parser.add_argument(
        "--check",
        action="store_true",
        help="Compatibility flag for generated-fixture stale-check manifests.",
    )
    parser.add_argument(
        "--write-inventory",
        action="store_true",
        help="Rewrite the checked-in script inventory.",
    )
    return parser.parse_args()


def fixture_scripts() -> list[Path]:
    fixture_dirs = (FIXTURE_DIR, PARSER_FIXTURE_DIR)
    return sorted(
        script_path
        for fixture_dir in fixture_dirs
        for script_path in fixture_dir.glob(SCRIPT_GLOB)
        if script_path.is_file()
    )


def check_inventory(script_inventory: list[str]) -> list[str]:
    expected_inventory = read_inventory()
    if expected_inventory == script_inventory:
        return []

    expected_set = set(expected_inventory)
    actual_set = set(script_inventory)
    errors = ["HTML fixture script inventory is stale."]

    missing = sorted(actual_set - expected_set)
    stale = sorted(expected_set - actual_set)
    if missing:
        errors.append(
            "missing from inventory:\n" + "\n".join(f"  {path}" for path in missing)
        )
    if stale:
        errors.append(
            "stale inventory entries:\n" + "\n".join(f"  {path}" for path in stale)
        )
    errors.append(
        "Run "
        "python3 code/packages/rust/html-lexer/tests/fixtures/"
        "check_html_fixture_scripts_compile.py --write-inventory"
    )
    return errors


def read_inventory() -> list[str]:
    return [
        line.strip()
        for line in SCRIPT_INVENTORY.read_text(encoding="utf-8").splitlines()
        if line.strip() and not line.startswith("#")
    ]


def write_inventory(script_inventory: list[str]) -> None:
    lines = [
        "# Generated by check_html_fixture_scripts_compile.py --write-inventory",
        "# Relative to code/packages/rust.",
        *script_inventory,
    ]
    SCRIPT_INVENTORY.write_text("\n".join(lines) + "\n", encoding="utf-8")


def relative_script(path: Path) -> str:
    try:
        return str(path.relative_to(RUST_DIR))
    except ValueError:
        return str(path)


if __name__ == "__main__":
    raise SystemExit(main())
